package io.github.diodeme.ji.spring;

import io.github.diodeme.ji.cli.LocalHostApplication;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;

/** Optional Spring composition adapter; Agent Core remains framework independent. */
@AutoConfiguration
@EnableConfigurationProperties(JiHostProperties.class)
@ConditionalOnProperty(prefix = "ji.host", name = "enabled", havingValue = "true")
public class JiHostAutoConfiguration {
    @Bean(destroyMethod = "close")
    @ConditionalOnMissingBean
    LocalHostApplication jiLocalHostApplication(JiHostProperties properties) throws IOException {
        Map<String, String> configuration = new LinkedHashMap<>();
        configuration.put("JI_DATA_DIR", properties.dataDirectory().toString());
        configuration.put("JI_WORKSPACE_ROOT", properties.workspaceRoot().toString());
        configuration.put("JI_LLM_MODEL", required(properties.model(), "ji.host.model"));
        configuration.put("JI_LLM_BASE_URL", required(properties.baseUrl(), "ji.host.base-url"));
        configuration.put("JI_HOST_PORT", Integer.toString(properties.port()));
        return LocalHostApplication.open(Map.copyOf(configuration));
    }

    private static String required(String value, String name) {
        if (value.isBlank()) throw new IllegalArgumentException(name + " is required");
        return value;
    }
}
